INSERT INTO giulia_memoria (from_numero, role, content, metadata) VALUES
  ('{{ $json.sender_numero }}', 'user', '{{ ($json.texto_original || '').replace(/'/g, "''") }}', NULL),
  ('{{ $json.sender_numero }}', 'assistant', '{{ ($json.resposta_final || '').replace(/'/g, "''") }}', NULL);
